use std::collections::HashSet;

/// Remove duplicates from a vector of i32, preserving no particular order.
///
/// The returned vector has no duplicates, and its elements form exactly the same set as the input.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();

    for &x in nums.iter() {
        if seen.insert(x) {
            res.push(x);
        }
    }

    res
}

